script:
export const meta = {
  name: "investment-gather-judge",
  description: "Enforced research/judge separation for financial decisions. Gather workers return evidence only; judge receives only evidence packets in a fresh context.",
  phases: [
    { title: "Brief" },
    { title: "Gather" },
    { title: "Judge" },
    { title: "Verify" },
  ],
}

const question = args.question || "Assess current risk/reward for portfolio rebalancing"
const symbols = args.symbols || ""

// Worker result contract — evidence-only for gatherers
const EVIDENCE_CONTRACT = {
  type: "object",
  required: ["outcome", "evidence", "changes", "decisions", "failures_risks", "new_tasks", "payload_json"],
  properties: {
    outcome: { type: "string", description: "What data was gathered, 1-2 sentences. NO recommendations." },
    evidence: { type: "string", description: "Raw data: prices, fundamentals, signals, sentiment. Cited. NO conclusions." },
    changes: { type: "array", items: { type: "string" } },
    decisions: { type: "array", items: { type: "string" }, description: "MUST be empty array. Gatherers do not decide." },
    failures_risks: { type: "array", items: { type: "string" }, description: "Data quality issues, missing sources, staleness" },
    new_tasks: { type: "array", items: { type: "string" } },
    payload_json: { type: "string", description: "Structured evidence as JSON string: { subtask, data_points: [{metric, value, source, timestamp, confidence}], raw_notes }" },
  },
}

const JUDGE_CONTRACT = {
  type: "object",
  required: ["outcome", "evidence", "changes", "decisions", "failures_risks", "new_tasks", "payload_json"],
  properties: {
    outcome: { type: "string", description: "Recommendation with confidence level, 2-3 sentences" },
    evidence: { type: "string", description: "Which evidence packets support/oppose the recommendation, cited by subtask ID" },
    changes: { type: "array", items: { type: "string" } },
    decisions: { type: "array", items: { type: "string" }, description: "Each decision with rationale and evidence citation" },
    failures_risks: { type: "array", items: { type: "string" }, description: "Conflicting signals, ignored evidence, calibration concerns" },
    new_tasks: { type: "array", items: { type: "string" } },
    payload_json: { type: "string", description: "JSON: { recommendation, confidence: high|medium|low, supporting_evidence: [subtask_ids], opposing_evidence: [subtask_ids], risk_flags: [strings], time_horizon }" },
  },
}

const VERIFY_CONTRACT = {
  type: "object",
  required: ["outcome", "evidence", "changes", "decisions", "failures_risks", "new_tasks", "payload_json"],
  properties: {
    outcome: { type: "string", description: "Verification result: PASS or FAIL with reason, 2-3 sentences" },
    evidence: { type: "string", description: "Specific checks performed and findings" },
    changes: { type: "array", items: { type: "string" } },
    decisions: { type: "array", items: { type: "string" } },
    failures_risks: { type: "array", items: { type: "string" }, description: "Any verification failures with severity" },
    new_tasks: { type: "array", items: { type: "string" } },
    payload_json: { type: "string", description: "JSON: { verdict: pass|fail, checks: [{name, passed, detail}], critical_failures: [strings] }" },
  },
}

// ── Phase 1: BRIEF (small model, fresh context) ──
phase("Brief")
let brief = null
try {
  brief = await agent(
    `You are a research architect for investment decisions. Your ONLY job is to create a research brief — you do not gather data and you do not make recommendations.

Investment question: ${question}
Symbols: ${symbols}

Output a research brief with:
1. 4-6 sub-questions that, if answered with data, would inform the investment decision
2. For each sub-question: what specific data to gather (prices, fundamentals, sentiment, technicals, macro)
3. What evidence would SUPPORT each possible action (buy/hold/sell/rebalance)
4. What evidence would OPPOSE each possible action

Return the worker contract JSON. Put the brief in payload_json as: { subtasks: [{ id, question, data_to_gather, supporting_signals, opposing_signals }] }`,
    { label: "architect-brief", tier: "small", schema: EVIDENCE_CONTRACT }
  )
} catch (err) {
  return { report: `investment-gather-judge: brief phase failed (${String(err)}). Nothing was gathered.`, incomplete: true }
}

let briefPayload = null
if (brief && typeof brief.payload_json === "string") {
  try { briefPayload = JSON.parse(brief.payload_json) } catch { briefPayload = null }
}
if (!briefPayload || !briefPayload.subtasks || !Array.isArray(briefPayload.subtasks)) {
  return { report: "investment-gather-judge: architect produced no usable subtasks. Aborting before gather.", incomplete: true, brief }
}

log(`Brief created with ${briefPayload.subtasks.length} subtasks`)

// ── Phase 2: GATHER (small model, parallel, each fresh context) ──
phase("Gather")
const subtasks = briefPayload.subtasks.slice(0, 8) // bound fan-out
const gatherPromises = subtasks.map((st) =>
  agent(
    `You are an evidence gatherer for investment research. Your ONLY job is to gather raw data. You do NOT make recommendations. You do NOT draw conclusions. You do NOT interpret.

Subtask ID: ${st.id}
Sub-question: ${st.question}
Data to gather: ${st.data_to_gather}
Symbols: ${symbols}

Gather the data. Return raw evidence only — prices, fundamentals, signals, sentiment scores, macro indicators. Every data point needs a source and timestamp.

CRITICAL: Your 'decisions' field MUST be an empty array. You are a gatherer, not a decider. If you include any recommendation or conclusion in 'decisions', the workflow will reject your output.

Return the worker contract JSON. Put structured evidence in payload_json as: { subtask_id: "${st.id}", data_points: [{metric, value, source, timestamp, confidence}], raw_notes: "..." }`,
    { label: `gather-${st.id}`, tier: "small", schema: EVIDENCE_CONTRACT }
  )
)

let gatherResults = []
try {
  gatherResults = await parallel(gatherPromises)
} catch (err) {
  return { report: `investment-gather-judge: gather phase failed (${String(err)}). Brief was created.`, incomplete: true, brief }
}

// Enforce: gatherers must not have made decisions
const violations = gatherResults.filter((r) => r && Array.isArray(r.decisions) && r.decisions.length > 0)
if (violations.length > 0) {
  log(`WARNING: ${violations.length} gatherer(s) returned decisions despite instructions. Stripping before judge phase.`)
}

// Extract evidence packets — judge gets ONLY these, never full worker contexts
const evidencePackets = gatherResults
  .filter((r) => r && r.payload_json)
  .map((r) => {
    let parsed = null
    try { parsed = JSON.parse(r.payload_json) } catch { parsed = null }
    return {
      subtask_id: parsed?.subtask_id || "unknown",
      data_points: parsed?.data_points || [],
      raw_notes: parsed?.raw_notes || r.evidence || "",
      data_quality_issues: (r.failures_risks || []),
    }
  })
  .filter((p) => p.data_points.length > 0 || p.raw_notes.length > 0)

if (evidencePackets.length === 0) {
  return {
    report: "investment-gather-judge: no usable evidence packets gathered. Aborting before judge phase — no financial decision should be made without evidence.",
    incomplete: true,
    brief,
    gather: gatherResults.map((r) => ({ outcome: r?.outcome, failures: r?.failures_risks })),
  }
}

log(`Gathered ${evidencePackets.length} evidence packets from ${gatherResults.length} workers`)

// ── Phase 3: JUDGE (big model, FRESH context — receives only evidence packets) ──
phase("Judge")
let judgment = null
try {
  judgment = await agent(
    `You are the investment judge. You receive pre-gathered evidence packets from multiple independent gatherers. You did NOT gather this data yourself — you are evaluating it fresh.

Investment question: ${question}
Symbols: ${symbols}

Evidence packets (JSON):
${JSON.stringify(evidencePackets, null, 2)}

Your job:
1. Weigh ALL evidence packets. Identify conflicting signals between packets.
2. For each possible action (buy/hold/sell/rebalance), cite which evidence packets support and which oppose it.
3. Produce a recommendation with explicit confidence level (high/medium/low).
4. Flag risks: what evidence is missing, what would change the recommendation, what data quality issues affect confidence.
5. State your time horizon assumption.

You must cite evidence by subtask_id. If you cannot support a claim with a specific evidence packet, state that explicitly.

Return the worker contract JSON. Put your structured recommendation in payload_json.
`,
    { label: "judge-evidence", tier: "big", schema: JUDGE_CONTRACT }
  )
} catch (err) {
  return {
    report: `investment-gather-judge: judge phase failed (${String(err)}). Evidence was gathered but no judgment was produced. Do NOT act on raw evidence.",
    incomplete: true,
    brief,
    evidencePackets,
  }
}

let judgePayload = null
if (judgment && typeof judgment.payload_json === "string") {
  try { judgePayload = JSON.parse(judgment.payload_json) } catch { judgePayload = null }
}

// ── Phase 4: VERIFY (medium model, FRESH context — adversarial review of judge) ──
phase("Verify")
let verification = null
try {
  verification = await agent(
    `You are an adversarial verifier for an investment recommendation. Your job is to find what's wrong with it.

Original investment question: ${question}

Judge's recommendation (JSON):
${JSON.stringify(judgePayload, null, 2)}

Judge's reasoning:
${judgment?.outcome || ""}

Evidence packets the judge had access to (JSON):
${JSON.stringify(evidencePackets, null, 2)}

Verify:
1. Did the judge cite specific evidence packets for each claim? Flag any unsupported claims.
2. Did the judge ignore any evidence packet? Check each subtask_id is referenced.
3. Is the confidence level calibrated? Does the evidence quality support the stated confidence?
4. What scenario would make this recommendation wrong? Is it acknowledged in risk flags?
5. Are there data quality issues that undermine the recommendation?

Verdict: PASS if the recommendation is well-supported and risks are adequately flagged. FAIL if there are unsupported claims, ignored evidence, or unacknowledged risks.

Return the worker contract JSON. Put verification results in payload_json.
`,
    { label: "verify-recommendation", tier: "medium", schema: VERIFY_CONTRACT }
  )
} catch (err) {
  log(`Verify phase failed (${String(err)}). Delivering judgment without adversarial verification.`)
  verification = { outcome: "Verification phase failed — judgment delivered WITHOUT adversarial review.", payload_json: JSON.stringify({ verdict: "skipped", critical_failures: ["verify phase error"] }) }
}

let verifyPayload = null
if (verification && typeof verification.payload_json === "string") {
  try { verifyPayload = JSON.parse(verification.payload_json) } catch { verifyPayload = null }
}

log("investment-gather-judge complete")

return {
  report: `Investment research complete with enforced gather/judge separation.

Question: ${question}

RECOMMENDATION: ${judgment?.outcome || "No judgment produced"}
Confidence: ${judgePayload?.confidence || "unknown"}
Time horizon: ${judgePayload?.time_horizon || "not stated"}

VERIFICATION: ${verifyPayload?.verdict || "unknown"}
${(verifyPayload?.critical_failures || []).length > 0 ? "CRITICAL FAILURES: " + verifyPayload.critical_failures.join("; ") : "No critical failures"}

Evidence packets gathered: ${evidencePackets.length}
Subtasks investigated: ${subtasks.length}
Risk flags: ${(judgePayload?.risk_flags || []).join("; ") || "none"}`,
  question,
  symbols,
  brief: { subtasks: subtasks.length, outcome: brief.outcome },
  gather: { packets: evidencePackets.length, workers: gatherResults.length, decision_violations: violations.length },
  judge: { recommendation: judgePayload?.recommendation || judgment?.outcome, confidence: judgePayload?.confidence, risk_flags: judgePayload?.risk_flags },
  verify: { verdict: verifyPayload?.verdict, failures: verifyPayload?.critical_failures || [], checks: verifyPayload?.checks || [] },
}
